function productImage(array $product): string { return trim((string)($product['image'] ?? '')); }
function productCard(array $product): void { $image = productImage($product); ?>
<article class="market-card"><a class="market-image" href="<?= e(BASE_URL) ?>/shop/product-details.php?id=<?= (int)$product['id'] ?>"><?php if ($image): ?><img src="<?= e($image) ?>" alt="<?= e($product['name']) ?>"><?php else: ?><span><?= e(strtoupper(substr((string)$product['name'],0,1))) ?></span><?php endif; ?></a><div class="market-card-body"><small><?= e($product['category_name'] ?? 'General merchandise') ?></small><h3><a href="<?= e(BASE_URL) ?>/shop/product-details.php?id=<?= (int)$product['id'] ?>"><?= e($product['name']) ?></a></h3><strong><?= e(formatPrice($product['wholesale_price'] ?? $product['retail_price'] ?? 0)) ?></strong><?php if (!empty($product['wholesale_price'])): ?><span class="unit"> / <?= e($product['unit'] ?? 'unit') ?></span><?php endif; ?><p><?= isset($product['minimum_order_quantity']) ? 'MOQ ' . (int)$product['minimum_order_quantity'] . ' ' . e($product['unit'] ?? 'units') : 'Ready to ship' ?></p></div></article>
